document.getElementById("login_form").addEventListener("submit", function(e) {
  e.preventDefault();

  const email = document.querySelector('#login_form input[type="text"]').value;
  const password = document.querySelector('#login_form #password').value;

  fetch('/api/method/login', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      usr: email,
      pwd: password
    })
  })
  .then(response => response.json())
  .then(data => {
    if (data.full_name) {
      Toastify({
        text: `👋 Welcome ${data.full_name}!`,
        close: true,
        gravity: "top",
        position: "center",
        stopOnFocus: true,
        style: {
          background: "var(--primary-color)",
        }
      }).showToast();

      setTimeout(() => {
        window.location.href = safeRedirect() || data.home_page || '/';
      }, 1200);
    } else {
      Toastify({
        text: "❌ Invalid credentials. Please try again.",
        close: true,
        gravity: "top",
        position: "center",
        stopOnFocus: true,
        style: {
          background: "var(--primary-color-light)",
        }
      }).showToast();
    }
  })
  .catch(error => {
    console.error('Login error:', error);
    Toastify({
      text: "⚠️ An error occurred during login. Please try again later.",
      close: true,
      gravity: "top",
      position: "center",
      stopOnFocus: true,
      style: {
        background: "var(--primary-color-light)",
      }
    }).showToast();
  });
});


