document.addEventListener("click", function (e) {
    const btn = e.target.closest(".pay_btn");
    if (!btn) return;

    const apiUrl = btn.dataset.url;
    if (!apiUrl) {
        console.error("No API URL found on button");
        return;
    }

    // prevent multiple clicks
    btn.disabled = true;
    window.location.href = apiUrl;
});


