document.querySelectorAll('.order_details_btn').forEach(button => {
  button.addEventListener('click', () => {
    const tab0 = document.querySelector('#tab-0');
    const orderSection = button.closest('.order_section');
    const orderDetails = orderSection.querySelector('.order_details');

    // Save current tab-0 content (excluding orderDetails)
    previousTabContent = tab0.innerHTML;

    // Save original parent of orderDetails
    originalParent = orderSection;

    // Hide everything in tab-0
    tab0.innerHTML = '';

    // Move orderDetails to tab-0 and show it
    tab0.appendChild(orderDetails);
    orderDetails.style.display = 'block';
  });
});

document.addEventListener('click', (e) => {
  if (e.target.closest('.order_back_btn')) {
    const tab0 = document.querySelector('#tab-0');
    const orderDetails = tab0.querySelector('.order_details');

    // Hide orderDetails
    orderDetails.style.display = 'none';

    // Restore tab-0 content
    tab0.innerHTML = previousTabContent;

    // Re-inject the hidden orderDetails back to its original place
    if (originalParent) {
      originalParent.appendChild(orderDetails);
    }

    // Re-bind events since we replaced tab content
    rebindButtons();
  }
});

// Function to reattach events after DOM replacement
function rebindButtons() {
  document.querySelectorAll('.order_details_btn').forEach(button => {
    button.addEventListener('click', () => {
      const tab0 = document.querySelector('#tab-0');
      const orderSection = button.closest('.order_section');
      const orderDetails = orderSection.querySelector('.order_details');

      previousTabContent = tab0.innerHTML;
      originalParent = orderSection;

      tab0.innerHTML = '';
      tab0.appendChild(orderDetails);
      orderDetails.style.display = 'block';
    });
  });
}


document.getElementById("logout").addEventListener("click", async function () {
  try {
    // logout is POST-only in this Frappe version (a GET returns an HTML error page)
    const response = await fetch("/api/method/logout", {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "X-Frappe-CSRF-Token": frappe.csrf_token,
        "Accept": "application/json"
      }
    });

    if (response.ok) {
      document.cookie = "cart_count=0; path=/;";
      window.location.href = "/";
    } else {
      let message = "Logout failed";
      try {
        const data = await response.json();
        message = data.message || message;
      } catch (parseError) {
        // response was not JSON; keep the generic message
      }
      throw new Error(message);
    }
  } catch (error) {
    console.error("Logout error:", error);
    Toastify({
      text: error.message || "Something went wrong during logout.",
      close: true,
      gravity: "top",
      position: "center",
      style: {
        background: "linear-gradient(to right, #ff416c, #ff4b2b)",
      },
    }).showToast();
  }
});


document.addEventListener('click', async function(e) {
    const btn = e.target.closest('.download_invoice');
    if (!btn) return;

    const orderName = btn.getAttribute('data-name');
    if (!orderName) {
        console.error('No order name found on download button');
        return;
    }

    btn.disabled = true;
    btn.innerHTML = '<p>Please wait...</p>';

    try {
        // Step 1: Find the Sales Invoice + print format for this Sales Order
        const invoiceRes = await fetch(
            `/api/method/storekit.api.invoice.get_sales_invoice_for_order?sales_order=${encodeURIComponent(orderName)}`,
            {
                method: 'GET',
                headers: {
                    'x-frappe-csrf-token': frappe.csrf_token,
                    'x-requested-with': 'XMLHttpRequest',
                    'Accept': 'application/json'
                }
            }
        );

        const invoiceData = await invoiceRes.json();
        const result = invoiceData.message;

        // Step 2: Check if invoice was found
        if (!result?.success) {
            Toastify({
                text: result?.message || 'No invoice found for this order.',
                close: true,
                gravity: 'top',
                position: 'center',
                duration: 5000,
                style: { background: 'var(--primary-color-light)' }
            }).showToast();
            return;
        }

        const invoiceName = result.invoice_name;
        const printFormat = result.print_format;

        // Step 3: Download the PDF using the dynamic print format
        const pdfUrl = `/api/method/frappe.utils.print_format.download_pdf?doctype=Sales%20Invoice&name=${encodeURIComponent(invoiceName)}&format=${encodeURIComponent(printFormat)}&no_letterhead=0`;

        const pdfRes = await fetch(pdfUrl, {
            method: 'GET',
            headers: {
                'x-frappe-csrf-token': frappe.csrf_token,
            }
        });

        if (!pdfRes.ok) throw new Error(`PDF download failed: HTTP ${pdfRes.status}`);

        const blob = await pdfRes.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Invoice-${invoiceName}.pdf`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        window.URL.revokeObjectURL(url);

        Toastify({
            text: 'Invoice downloaded successfully!',
            close: true,
            gravity: 'top',
            position: 'center',
            style: { background: 'var(--primary-color)' }
        }).showToast();

    } catch (err) {
        console.error('Invoice download error:', err);
        Toastify({
            text: 'Something went wrong. Please try again later.',
            close: true,
            gravity: 'top',
            position: 'center',
            style: { background: 'linear-gradient(to right, #ff416c, #ff4b2b)' }
        }).showToast();
    } finally {
        btn.disabled = false;
        btn.innerHTML = '<p>Download Invoice</p>';
    }
});

/* ================= HELPER FUNCTIONS ================= */
function updateURLParam(key, value, isArray = false, reload = true) {
  const params = new URLSearchParams(window.location.search);
  if (isArray) {
    params.delete(key + '[]');
    if (Array.isArray(value) && value.length > 0) {
      value.forEach(v => params.append(key + '[]', v));
    }
  } else {
    if (value === null || value === '') {
      params.delete(key);
    } else {
      params.set(key, value);
    }
  }
  const newUrl = `${window.location.pathname}?${params.toString()}`;
  if (reload) {
    window.location.href = newUrl;
  } else {
    window.history.replaceState({}, "", newUrl);
  }
}

function getURLParams(key, isArray = false) {
  const params = new URLSearchParams(window.location.search);
  return isArray ? params.getAll(key + '[]') : params.get(key);
}

