function showTab(tabIndex) {
    let tabs = document.querySelectorAll('.tab');
    tabs.forEach(tab => tab.classList.remove('active'));
    document.getElementById(`tab-${tabIndex}`).classList.add('active');
    document.querySelectorAll('.tab-button').forEach((button, i) => {
        button.classList.toggle('active', i === tabIndex);
    });

    // Hide address_create_form if it's visible
    const addressForm = document.getElementById('address_create_form');
    if (addressForm && addressForm.style.display !== 'none') {
        addressForm.style.display = 'none';
    }
    const tab0 = document.getElementById('tab-3');
    if (tab0 && tab0.hasAttribute('style')) {
        tab0.removeAttribute('style');
    }
}

