let previousTabContent = null;
let originalParent = null;

document.querySelectorAll('.order_details_btn').forEach(button => {
  button.addEventListener('click', () => {
    const tab0 = document.querySelector('#tab-0');
    const orderSection = button.closest('.order_section');
    const orderDetails = orderSection.querySelector('.order_details');

    // Save current tab-0 content (excluding orderDetails)
    previousTabContent = tab0.innerHTML;

    // Save original parent of orderDetails
    originalParent = orderSection;

    // Hide everything in tab-0
    tab0.innerHTML = '';

    // Move orderDetails to tab-0 and show it
    tab0.appendChild(orderDetails);
    orderDetails.style.display = 'block';
  });
});

document.addEventListener('click', (e) => {
  if (e.target.classList.contains('order_back_btn')) {
    const tab0 = document.querySelector('#tab-0');
    const orderDetails = tab0.querySelector('.order_details');

    // Hide orderDetails
    orderDetails.style.display = 'none';

    // Restore tab-0 content
    tab0.innerHTML = previousTabContent;

    // Re-inject the hidden orderDetails back to its original place
    if (originalParent) {
      originalParent.appendChild(orderDetails);
    }

    // Re-bind events since we replaced tab content
    rebindButtons();
  }
});

// Function to reattach events after DOM replacement
function rebindButtons() {
  document.querySelectorAll('.order_details_btn').forEach(button => {
    button.addEventListener('click', () => {
      const tab0 = document.querySelector('#tab-0');
      const orderSection = button.closest('.order_section');
      const orderDetails = orderSection.querySelector('.order_details');

      previousTabContent = tab0.innerHTML;
      originalParent = orderSection;

      tab0.innerHTML = '';
      tab0.appendChild(orderDetails);
      orderDetails.style.display = 'block';
    });
  });
}


document.getElementById("logout").addEventListener("click", async function () {
  try {
    // logout is POST-only in this Frappe version (a GET returns an HTML error page)
    const response = await fetch("/api/method/logout", {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "X-Frappe-CSRF-Token": frappe.csrf_token,
        "Accept": "application/json"
      }
    });

    if (response.ok) {
      window.location.href = "/";
    } else {
      let message = "Logout failed";
      try {
        const data = await response.json();
        message = data.message || message;
      } catch (parseError) {
        // response was not JSON; keep the generic message
      }
      throw new Error(message);
    }
  } catch (error) {
    console.error("Logout error:", error);
    Toastify({
      text: error.message || "Something went wrong during logout.",
      close: true,
      gravity: "top",
      position: "center",
      style: {
        background: "linear-gradient(to right, #ff416c, #ff4b2b)",
      },
    }).showToast();
  }
});

