/* ── Product card text colors ─────────────────────────── */
.product-title {
  color: var(--primary-text-color);
}
.product-price {
  color: var(--primary-text-color);
  font-size: 13px;
}
.product-price + .product-price {
  color: var(--primary-color);
  font-weight: 600;
}

/* ── Custom modal overlay ─────────────────────────────── */
.custom-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.45);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
}
.custom-modal {
  background: #ffffff;
  border-radius: 10px;
  min-width: 320px;
  max-width: 500px;
  width: 92%;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.18);
}
.custom-modal-header {
  background: var(--btn-bg);
  color: var(--btn-color);
  padding: 16px 20px;
  font-size: 16px;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.custom-modal-close {
  cursor: pointer;
  font-size: 20px;
  background: none;
  border: none;
  color: var(--btn-color);
  line-height: 1;
  padding: 0;
}
.custom-modal-body {
  padding: 20px;
  max-height: 60vh;
  overflow-y: auto;
}
.custom-modal-footer {
  padding: 12px 20px;
  border-top: 1px solid var(--primary-color-faint);
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  background: #fafafa;
}

/* ── Variant form ─────────────────────────────────────── */
.variant-form { margin: 0; }
.variant-group { margin-bottom: 16px; }
.variant-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary-text-color);
  margin-bottom: 8px;
}
.variant-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.variant-option input[type="radio"] { display: none; }
.variant-pill {
  padding: 6px 14px;
  border: 1.5px solid var(--primary-color-faint);
  border-radius: 20px;
  cursor: pointer;
  font-size: 13px;
  color: var(--primary-text-color);
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.variant-option input:checked + .variant-pill {
  background: var(--btn-bg);
  color: var(--btn-color);
